const text = String($json.message?.text || '').trim();
const chatId = $json.message?.chat?.id;

const UF_TO_STATE = {
  AC: 'Acre', AL: 'Alagoas', AP: 'Amapá', AM: 'Amazonas',
  BA: 'Bahia', CE: 'Ceará', DF: 'Distrito Federal', ES: 'Espírito Santo',
  GO: 'Goiás', MA: 'Maranhão', MT: 'Mato Grosso', MS: 'Mato Grosso do Sul',
  MG: 'Minas Gerais', PA: 'Pará', PB: 'Paraíba', PR: 'Paraná',
  PE: 'Pernambuco', PI: 'Piauí', RJ: 'Rio de Janeiro', RN: 'Rio Grande do Norte',
  RS: 'Rio Grande do Sul', RO: 'Rondônia', RR: 'Roraima', SC: 'Santa Catarina',
  SP: 'São Paulo', SE: 'Sergipe', TO: 'Tocantins'
};

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

if (!text.includes(',')) {
  return [{
    json: {
      valid: false,
      chatId,
      message: 'Envie no formato: Cidade, UF\nExemplo: Campinas, SP'
    }
  }];
}

const commaIndex = text.indexOf(',');
const cidade = text.slice(0, commaIndex).trim();
const estadoRaw = text.slice(commaIndex + 1).trim();

if (!cidade || !estadoRaw) {
  return [{
    json: {
      valid: false,
      chatId,
      message: 'Envie no formato: Cidade, UF\nExemplo: Campinas, SP'
    }
  }];
}

const estadoUpper = estadoRaw.toUpperCase();
let uf = null;
let estadoNome = null;

if (UF_TO_STATE[estadoUpper]) {
  uf = estadoUpper;
  estadoNome = UF_TO_STATE[estadoUpper];
} else {
  const match = Object.entries(UF_TO_STATE).find(([, name]) => normalize(name) === normalize(estadoRaw));
  if (match) {
    uf = match[0];
    estadoNome = match[1];
  }
}

if (!uf || !estadoNome) {
  return [{
    json: {
      valid: false,
      chatId,
      message: 'Não reconheci esse estado. Use a UF (ex.: SP) ou o nome completo (ex.: São Paulo).'
    }
  }];
}

return [{
  json: {
    valid: true,
    chatId,
    cidade,
    uf,
    estadoNome,
    estadoNorm: normalize(estadoNome)
  }
}];

const parsed = $json;
const apiKey = $env.OPENWEATHER_API_KEY;

if (!apiKey) {
  return [{
    json: {
      found: false,
      chatId: parsed.chatId,
      message: 'A chave OPENWEATHER_API_KEY não está configurada no container.'
    }
  }];
}

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

let candidates = [];
try {
  candidates = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.openweathermap.org/geo/1.0/direct',
    qs: {
      q: `${parsed.cidade},BR`,
      limit: 5,
      appid: apiKey
    },
    json: true
  });
} catch (error) {
  return [{
    json: {
      found: false,
      chatId: parsed.chatId,
      message: 'Não consegui localizar a cidade agora. Tente novamente em instantes.'
    }
  }];
}

if (!Array.isArray(candidates)) {
  candidates = [];
}

const match = candidates.find((item) => {
  if (String(item.country || '').toUpperCase() !== 'BR') return false;
  return normalize(item.state) === parsed.estadoNorm;
});

if (!match) {
  return [{
    json: {
      found: false,
      chatId: parsed.chatId,
      message: `Não encontrei ${parsed.cidade} em ${parsed.uf}. Confira o nome da cidade e a UF.`
    }
  }];
}

return [{
  json: {
    found: true,
    chatId: parsed.chatId,
    cidade: parsed.cidade,
    uf: parsed.uf,
    estadoNome: parsed.estadoNome,
    name: match.name || parsed.cidade,
    lat: match.lat,
    lon: match.lon
  }
}];

const location = $('Geocode e Filtrar Estado').first().json;
const weather = $json;

if (!weather || weather.cod === '401' || weather.cod === 401) {
  return [{
    json: {
      chatId: location.chatId,
      text: 'Não consegui consultar o clima agora. Verifique a chave da OpenWeather e tente de novo.'
    }
  }];
}

if (!weather.main || weather.main.temp == null) {
  return [{
    json: {
      chatId: location.chatId,
      text: 'Não encontrei dados de temperatura para essa cidade. Tente novamente.'
    }
  }];
}

const temp = Math.round(Number(weather.main.temp));
const description = weather.weather?.[0]?.description || 'condições estáveis';
const cityLabel = location.name || location.cidade;

return [{
  json: {
    chatId: location.chatId,
    text: `Em ${cityLabel} (${location.uf}) está ${temp}°C agora, com ${description}.`
  }
}];
